"use client";

/**
 * AgentContext.tsx
 * ----------------
 * Shared state for the agent definition across the Define → Test → Improve flow.
 *
 * Holds:
 *   inputType       — what the user gives the agent (free text)
 *   outputType      — what the agent should produce (free text)
 *   policyDocId     — which policy document to ground on (dropdown key)
 *   agentInstructions — the current instruction string sent to the backend
 *
 * agentInstructions is derived from inputType + outputType on Save, and
 * updated (appended) when the user accepts an improvement suggestion.
 */

import React, { createContext, useContext, useState } from "react";

export interface AgentDef {
  inputType: string;
  outputType: string;
  policyDocId: string;
  agentInstructions: string;
}

const DEFAULT: AgentDef = {
  inputType: "",
  outputType: "",
  policyDocId: "service_policy",
  agentInstructions: "",
};

interface AgentContextValue {
  agentDef: AgentDef;
  setAgentDef: (def: AgentDef) => void;
}

const AgentContext = createContext<AgentContextValue>({
  agentDef: DEFAULT,
  setAgentDef: () => {},
});

export function AgentProvider({ children }: { children: React.ReactNode }) {
  const [agentDef, setAgentDef] = useState<AgentDef>(DEFAULT);
  return (
    <AgentContext.Provider value={{ agentDef, setAgentDef }}>
      {children}
    </AgentContext.Provider>
  );
}

export function useAgent() {
  return useContext(AgentContext);
}
